package runner

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/strio-dev/stoke/internal/workflow"
)

// Uses complete, prebuilt local OCI inputs; no registry or producer store is
// contacted. The fixture is generated by Coopr's existing Nix/Bale acceptance.
func TestCIComponentDeliverySelectionsWithCoopr(t *testing.T) {
	if testing.Short() {
		t.Skip("requires explicit development engine and local Nix/Bale OCI fixtures")
	}
	engine := os.Getenv("STOKE_COOPR_BINARY")
	fixturePath := os.Getenv("STOKE_CI_DELIVERY_FIXTURE")
	evidence := os.Getenv("STOKE_HOST_EVIDENCE_DIR")
	if engine == "" || fixturePath == "" || evidence == "" {
		t.Fatal("select STOKE_COOPR_BINARY, STOKE_CI_DELIVERY_FIXTURE and STOKE_HOST_EVIDENCE_DIR")
	}
	var inputs struct {
		Digest     string   `json:"digest"`
		Archives   []string `json:"archives"`
		Image      string   `json:"image"`
		Runtime    string   `json:"runtime"`
		Definition string   `json:"definition"`
	}
	data, err := os.ReadFile(fixturePath)
	if err != nil {
		t.Fatal(err)
	}
	if err := json.Unmarshal(data, &inputs); err != nil || len(inputs.Archives) != 2 || inputs.Image == "" {
		t.Fatal("invalid local delivery fixture", err)
	}
	root, err := os.MkdirTemp(evidence, "native-ci-delivery-")
	if err != nil {
		t.Fatal(err)
	}
	t.Log("Retained exact component delivery evidence:", root)
	caller := filepath.Join(root, "caller")
	if err := os.Mkdir(caller, 0700); err != nil {
		t.Fatal(err)
	}
	definition, err := os.ReadFile(inputs.Definition)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(caller, "unused.coopr"), definition, 0600); err != nil {
		t.Fatal(err)
	}
	if !strings.HasPrefix(inputs.Image, "oci:") || !strings.HasSuffix(inputs.Image, ":image") {
		t.Fatal("fixture requires a complete local OCI layout with image reference")
	}
	layout := strings.TrimSuffix(strings.TrimPrefix(inputs.Image, "oci:"), ":image")
	if err := os.CopyFS(filepath.Join(caller, "base"), os.DirFS(layout)); err != nil {
		t.Fatal(err)
	}
	policy := filepath.Join(root, "policy.json")
	if err := os.WriteFile(policy, []byte(`{"default":[{"type":"reject"}],"transports":{"oci":{"":[{"type":"insecureAcceptAnything"}]},"containers-storage":{"":[{"type":"insecureAcceptAnything"}]}}}`), 0600); err != nil {
		t.Fatal(err)
	}
	native := "arg \"LEFT\"\narg \"RIGHT\"\nfrom \"oci:base:image\" {\n arg \"LEFT\"\n arg \"RIGHT\"\n"
	for _, step := range []struct{ argument, message, proof string }{{"LEFT", "left", "proof-left"}, {"RIGHT", "right", "proof-right"}, {"LEFT", "left-again", "proof-left-again"}} {
		native += fmt.Sprintf(" component \"${%s}\" { arg \"message\" %q; arg \"tool\" \"/bin/true\"; }\n run { exec \"/bin/cp\" \"/proof\" %q; }\n", step.argument, step.message, "/"+step.proof)
	}
	native += "}\n"
	if err := os.WriteFile(filepath.Join(caller, "consumer.coopr"), []byte(native), 0600); err != nil {
		t.Fatal(err)
	}
	w, err := workflow.Decode(strings.NewReader(`version: 1
tasks:
  left: {coopr: {kind: component, files: [unused.coopr]}}
  right: {coopr: {kind: component, files: [unused.coopr]}}
  consume:
    cache: false
    coopr: {files: [consumer.coopr], args: {LEFT: {from: left}, RIGHT: {from: right}}}
`))
	if err != nil {
		t.Fatal(err)
	}
	imports := map[string]CIImport{
		"left":  {Kind: "component", OCI: inputs.Archives[0], Digest: inputs.Digest},
		"right": {Kind: "component", OCI: inputs.Archives[1], Digest: inputs.Digest},
	}
	ctx, cancel := context.WithTimeout(t.Context(), 5*time.Minute)
	defer cancel()
	var reports []*Report
	for i := range 4 {
		phase := filepath.Join(root, fmt.Sprintf("independent-%d", i))
		var stdout, stderr bytes.Buffer
		options := Options{ContextDir: caller, StateDir: filepath.Join(phase, "state"), CacheDir: filepath.Join(phase, "cache"), OutputDir: filepath.Join(phase, "output"), CooprBinary: engine, StorageDriver: "vfs", Runtime: inputs.Runtime, Network: "none", SignaturePolicy: policy}
		options.Stdout, options.Stderr = &stdout, &stderr
		if i >= 2 {
			// Keep independent native stores while restoring through the shared
			// Coopr cache. Imported component ARG values must stay identical.
			consumer := w.Tasks["consume"]
			consumer.Cache = nil
			w.Tasks["consume"] = consumer
			options.CacheDir = filepath.Join(root, "shared-cache")
		}
		report, err := RunCI(ctx, w, CIRequest{Execute: []string{"consume"}, Imports: imports}, options)
		for name, data := range map[string][]byte{"stdout.log": stdout.Bytes(), "stderr.log": stderr.Bytes()} {
			if writeErr := os.WriteFile(filepath.Join(phase, name), data, 0600); writeErr != nil {
				t.Fatal(writeErr)
			}
		}
		if err != nil {
			t.Fatal("exact delivery consumption failed", err)
		}
		if report.Status != "passed" || len(report.Tasks) != 1 {
			t.Fatal("imported component producers unexpectedly executed", report)
		}
		for path, expected := range map[string]string{"proof-left": "left", "proof-right": "right", "proof-left-again": "left-again"} {
			proof, err := os.ReadFile(filepath.Join(report.Tasks[0].Filesystem, path))
			if err != nil || strings.TrimSpace(string(proof)) != expected {
				t.Fatal("native component RUN produced wrong exact output", path, string(proof), err)
			}
		}
		// Native frontend results do not expose aggregate cache statistics.
		// Its existing progress stream records each restored instruction.
		if i == 3 && strings.Count(stderr.String(), "--> Using cache ") < 3 {
			t.Fatal("unchanged delivery selectors failed to restore from the shared cache in a fresh store", stderr.String())
		}
		reports = append(reports, report)
	}
	encoded, err := json.MarshalIndent(map[string]any{"status": "PASS", "reports": reports, "fixture": fixturePath, "firstTwoRunsFresh": true, "lastRunRestoredAcrossStores": true, "registryUsed": false}, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(root, "result.json"), append(encoded, '\n'), 0600); err != nil {
		t.Fatal(err)
	}
}
